insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('gaslift', 'beginner', 'module', 'm01-a-well-full-of-kill-fluid', 1, 'A dead well is described as full rather than empty. What is standing in it, and where does that quantity come from?', '["A column of kill fluid whose gradient is declared as a design input, 0.45 psi/ft on westTexasOil and 0.5 psi/ft on deepHighPressure, with nothing in the module computing it.", "A column of produced oil whose gradient the module derives from black oil correlations.", "A static gas column marched down from the surface injection pressure.", "An aerated lifted column standing at the declared 0.1 psi/ft."]'::jsonb, 0, 'Lifting means replacing part of that standing column with something lighter, so the gradient of the fluid being displaced fixes how many feet each surplus psi buys.'),
  ('gaslift', 'beginner', 'module', 'm01-a-well-full-of-kill-fluid', 2, 'Treating the injection gas as weightless, how far does the first bite of gas reach on westTexasOil against the depth the case is designed to?', '["About 2400 ft, which is the deepHighPressure figure.", "About 2119.249994721 ft, where valve 1 lands.", "About 2000 ft of reach against a target depth of 7500.0 ft.", "Roughly 7500.0 ft of reach, because the weightless arithmetic is what sets the target depth of a design in the first place and the string of valves merely fills in the space below it."]'::jsonb, 2, 'The gap between the weightless reach and the target depth is the whole subject of a gas lift string, and the weight of the real gas column closes only a fraction of it.'),
  ('gaslift', 'beginner', 'module', 'm01-a-well-full-of-kill-fluid', 3, 'Ranking the four published cases on kickoff pressure less unloading wellhead pressure divided by kill fluid gradient, which one reaches deepest?', '["constantPressurePPO, at 2261.904761905 ft, because its 0.42 psi/ft kill fluid is the lightest of the four and a lighter fluid always buys the most depth for a given head.", "deepHighPressure, at 2400.000000000 ft.", "westTexasOil, at 2000.000000000 ft.", "midDecrementKnifeEdge, at 2195.652173913 ft, since its 26.75 psi per valve decrement leaves the most surface pressure in hand at the first stage."]'::jsonb, 1, 'The lightest kill fluid does not win, because the head on top of it matters as much as the divisor: deepHighPressure carries 1200.0 psi of head into a 0.5 psi/ft fluid.'),
  ('gaslift', 'beginner', 'module', 'm01-a-well-full-of-kill-fluid', 4, 'Why is a design sized on the kickoff pressure optimistic at every depth in it?', '["Because the kickoff pressure is quoted at the wellhead and has to be corrected for the weight of the gas column before it means anything at depth.", "Because the kickoff pressure is a shut in casing figure and the compressor cannot in practice hold it for the length of an unloading sequence.", "Because the kickoff pressure ignores the transfer differential.", "Because the kickoff pressure is spent getting the fluid out and the well then runs on a lower operating pressure, 1014.7 psia against 914.7 psia on westTexasOil."]'::jsonb, 3, 'The 100 psi difference appears on three of the four published cases, 1414.7 against 1314.7 psia on deepHighPressure and 1164.7 against 1064.7 psia on midDecrementKnifeEdge.'),
  ('gaslift', 'beginner', 'module', 'm01-a-well-full-of-kill-fluid', 5, 'The four published strings carry 8, 7, 6 and 7 valves against declared limits of 12, 14, 10 and 12. What does that pattern say about how a string ends?', '["A string ends when the pressure runs out of room, since not one of the four came near exhausting its mandrels.", "A string ends when the valve limit is reached, and the declared limits are simply generous on these four cases.", "A string ends at a fixed number of valves chosen by the designer before any spacing is attempted, with the limits acting as the real control on depth.", "A string ends when the kill fluid gradient is finally exhausted by the injection column, which is why the counts sit below the limits."]'::jsonb, 0, 'Only one of the four published cases stops on minimum spacing, and none of them stops on the valve limit, so the mandrel count is rarely the binding constraint.'),
  ('gaslift', 'beginner', 'module', 'm01-a-well-full-of-kill-fluid', 6, 'Of the three lines a gas lift design is drawn with, how many are computed from gas properties?', '["Two, the injection line and the unloading line.", "One, the injection line, which is marched with a compressibility factor at every step.", "Three, since the injection line, the unloading line and the transfer line are each marched over pressure and temperature by the same routine that returns the gas gradient.", "None, because all three gradients are supplied as inputs and the module only does arithmetic on them."]'::jsonb, 1, 'The unloading and transfer lines are declared by the designer and carry no physics, which is worth recalling every time a design output looks precise.'),
  ('gaslift', 'beginner', 'module', 'm01-a-well-full-of-kill-fluid', 7, 'constantPressurePPO declares 0.00 psi per valve and holds 1114.7000 psia at all six stages. What does the recursion lean on instead?', '["Its 0.42 psi/ft kill fluid gradient, scaled up by the convention.", "Its 8500.0 ft target depth.", "Its 100.0 psi transfer differential, which is the only margin left once the surface pressure never falls.", "Its 800.0 Mscf/d design gas rate, felt in the annulus column."]'::jsonb, 2, 'The two conventions are one recursion with a different decrement, so a zero decrement changes what carries the design rather than changing the construction.'),
  ('gaslift', 'beginner', 'module', 'm01-a-well-full-of-kill-fluid', 8, 'The oracle and the shipped engine agree on the column at 8000 ft to 1.251e-4 psi. What is that agreement evidence of?', '["That two independent implementations carry out the same construction and land in the same place.", "That the construction is correct, since an independent implementation would have diverged if the underlying physics were wrong at any point in the march.", "That the engine reproduces the published golden to within the tolerance the extraction gate demands of it, which is the definition of a validated result.", "That the march has converged, because agreement at that size can only be reached once the step count is fine enough."]'::jsonb, 0, 'Where both sides share an assumption the agreement is silent, which is exactly how the minimum spacing exemption survives in the goldens without complaint.'),
  ('gaslift', 'beginner', 'module', 'm01-a-well-full-of-kill-fluid', 9, 'The flowing production traverse used to locate the deepest injection point is passed in as a depth and pressure table. Why?', '["Because the traverse changes with time and the module is a steady state calculation that cannot carry a time dependent input.", "Because the traverse is measured in the field and the module refuses to accept any correlated value in its place.", "Because tabulating it outside the module lets the design be run at several gas rates without recomputing the annulus column each time.", "Because the module solves neither inflow nor multiphase outflow, so the caller builds that traverse from a validated nodal model."]'::jsonb, 3, 'There is no inflow performance relation anywhere in the module, so it tells you where gas can reach and never whether the well then produces.'),
  ('gaslift', 'beginner', 'module', 'm01-a-well-full-of-kill-fluid', 10, 'Two designs run 500.0 Mscf/d and 250.0 Mscf/d down the same annulus. What does the casing column at depth do?', '["It rises with the higher rate, since friction in the annulus adds to the weight of the gas and the module accounts for both terms in the same march.", "It is identical, because the injection rate never enters a static column.", "It falls with the higher rate.", "It changes only below the point of injection, where the gas leaving the annulus alters the balance between the two columns."]'::jsonb, 1, 'The column takes surface pressure, gas gravity, temperature and depth alone, so a design that looks insensitive to rate is being honest about what a shut in column is.'),
  ('gaslift', 'beginner', 'module', 'm01-a-well-full-of-kill-fluid', 11, 'Why does nothing in this module fit an intermittently lifted well?', '["Because intermittent lift needs a larger port than the catalogue offers.", "Because intermittent wells unload on a different sequence entirely.", "Because an intermittent tubing gradient swings between a rising slug and an almost empty column, so there is no single lifted gradient to declare.", "Because the injection gas is delivered in cycles, and the static column routine would have to carry a time varying surface pressure it has no argument for."]'::jsonb, 2, 'The module header states plainly that everything in it is continuous lift, so an intermittent well calls for a different tool rather than a reinterpreted output.'),
  ('gaslift', 'beginner', 'module', 'm01-a-well-full-of-kill-fluid', 12, 'westTexasOil valve 1 is credited with 1359.548505991 Mscf/d against a 500.0 Mscf/d target. How should that number be read?', '["As a ceiling, because Thornhill and Craver is an orifice equation.", "As the rate the valve will pass in service, since the equation is fitted to measured gas lift valve performance across the catalogue of ports.", "As the rate at which the valve throttles on its stem, which is the practical limit a design is expected to work back from.", "As a lower bound, because an orifice equation neglects the acceleration of the gas through the port and so under reads the throughput available."]'::jsonb, 0, 'A real valve throttles on its stem before it is fully open, and nothing in the orifice equation knows that, so the margin over the target is smaller than it looks.'),
  ('gaslift', 'beginner', 'module', 'm01-a-well-full-of-kill-fluid', 13, 'westTexasOil lands a mandrel 131.375432376 ft from its neighbour against a stated 250.0 ft minimum and raises no warning about it. What does that silence tell you?', '["That the minimum spacing input is advisory, so the engine records a breach of it as information rather than raising it as a warning to the designer.", "That the branch pulling the last mandrel to target depth returns before the spacing test runs.", "That the spacing was measured along a different depth reference.", "That the design satisfies the minimum."]'::jsonb, 1, 'The absence of a warning is evidence about the code path taken and not about the design, which is why the goldens record the breach without complaint.'),
  ('gaslift', 'beginner', 'module', 'm01-a-well-full-of-kill-fluid', 14, 'westTexasOil raises three warnings on its published run. What are they about?', '["Minimum spacing, raised once for each of the three increments that fall inside the declared 250.0 ft floor of the design.", "Port sizing, where the catalogue cannot pass the 500.0 Mscf/d target at the differential available at three of the eight valve depths.", "A mixture of multipointing and minimum spacing.", "Multipointing, at stages 2, 3 and 4, where a valve above is still open."]'::jsonb, 3, 'Multipointing means the string injects at two depths at once, and it is the single most consequential boolean the design routine emits.'),
  ('gaslift', 'beginner', 'module', 'm01-a-well-full-of-kill-fluid', 15, 'The nitrogen dome charge uses Dranchuk and Abou-Kassem with nitrogen criticals. What does the module say about that use?', '["That it is exact, since the correlation is defined on reduced properties and so applies to any pure gas once its criticals are supplied.", "That it is corrected for nitrogen by the Wichert and Aziz shift before the reduced properties are formed.", "That it is an extrapolation off the natural gas basis the correlation was fitted to, defensible in a window pinned at Tpr 2.3 to 3.1 and Ppr 1 to 5.", "That it is validated against published nitrogen charts."]'::jsonb, 2, 'Naming the window a correlation is defensible in is a different act from asserting agreement with data, and the module header does the first only.'),
  ('gaslift', 'beginner', 'module', 'm02-the-injection-line', 1, 'Across the five published gas property cases the static gradient runs from 0.002112418 to 0.080711504 psi/ft. What does that range establish?', '["That the correlation is unreliable at the extremes of the published set, which is why a design leans on a single representative value instead.", "That gas gravity is the dominant control, the spread running from the 0.6 gravity case to the 0.8 gravity one.", "That the range is an artefact of reporting the gradient at nine decimal places when only the first two carry any meaning for a design.", "That a gradient belongs to a place in a well rather than to a gas, since it is density over 144 and density moves with pressure and temperature."]'::jsonb, 3, 'The same 0.65 gravity gas reads 0.011670185 psi/ft at 500.0 psia and 100.0 degF and 0.031855542 psi/ft at 1500.0 psia and 180.0 degF.'),
  ('gaslift', 'beginner', 'module', 'm02-the-injection-line', 2, 'One 0.65 gravity gas gives 0.011670185 psi/ft at 500.0 psia and 100.0 degF and 0.031855542 psi/ft at 1500.0 psia and 180.0 degF. What follows for a design?', '["That naming a single gradient for the injection gas throws away most of the quantity, because the conditions decide it rather than the gas.", "That the deeper condition is the one to quote, since it governs the valves.", "That the shallower reading should be discarded as outside the correlation.", "That gas gravity has to be re-measured whenever a design is revised."]'::jsonb, 0, 'Density rises with pressure and falls with temperature, so the two arguments pull opposite ways and neither can be dropped from the statement.'),
  ('gaslift', 'beginner', 'module', 'm02-the-injection-line', 3, 'z falls to 0.894419892 at 2500.0 psia and 220.0 degF and then climbs to 0.916168222 at 3500.0 psia and 250.0 degF. What does that show?', '["That the Dranchuk and Abou-Kassem fit is being used outside its window at the highest published pressure, which is where the reversal appears.", "That the 0.8 gravity of the deeper case lifts z back up.", "That z is not a function of pressure alone, since pressure on its own would have kept it falling.", "That z passes through a minimum at a fixed reduced pressure."]'::jsonb, 2, 'Both arguments matter and they pull opposite ways, which is why the compressibility factor has to be evaluated at each step of a march rather than fixed once.'),
  ('gaslift', 'beginner', 'module', 'm02-the-injection-line', 4, 'Down each of the three published columns z rises, on column 2 from 0.817110097 to 0.910514014. What does a rising z do to the gas?', '["It makes the gas heavier, because a larger compressibility factor packs more mass into the same volume at any given pressure and temperature.", "It makes the gas lighter, since density goes as pressure over z and temperature.", "It leaves density untouched and shows only that the gas is returning towards ideal behaviour as the column is marched down towards the packer.", "It makes the gas lighter, but only through the temperature term, z entering the gradient nowhere else."]'::jsonb, 1, 'The rising z is a second effect pushing the gas lighter with depth, working alongside the geotherm rather than against it.'),
  ('gaslift', 'beginner', 'module', 'm02-the-injection-line', 5, 'The published acid case at 0.75 gravity, 2000.0 psia and 160.0 degF returns z of 0.849475579 with the correction and 0.821584635 without it. What does Wichert and Aziz change?', '["The pseudo-criticals, shifting the temperature from 389.700000 to 372.934297 degR and the pressure from 656.525000 to 627.243695 psia.", "The compressibility factor directly, by an additive term applied after the correlation has been evaluated on the uncorrected criticals.", "The gas gravity used to form the criticals.", "The correlation itself, a separate sour gas fit replacing Dranchuk and Abou-Kassem once the acid mole fractions exceed a threshold."]'::jsonb, 0, 'Mole fractions of 0.08 and 0.04 look small yet move z by that much, and the error then compounds down the whole march in the direction of a heavier gas.'),
  ('gaslift', 'beginner', 'module', 'm02-the-injection-line', 6, 'On all three published columns, each carrying an ordinary linear geotherm, which way does the local gas gradient move between surface and packer?', '["It rises, by those same percentages, because the gas is compressed as it goes down and a compressed gas is a heavier one at every step of the march.", "It rises on the two high pressure columns and falls only on the 614.7 psia one, the direction depending on where the column sits in pressure.", "It holds steady to within a tenth of a percent, the compression and the geotherm cancelling almost exactly on an ordinary well.", "It falls, by 2.0156, 4.9023 and 2.0201 percent."]'::jsonb, 3, 'Compression pushes the gradient up and the rising geotherm pushes it down, and on these three columns the geotherm outruns the compression.'),
  ('gaslift', 'beginner', 'module', 'm02-the-injection-line', 7, 'Column 1 is held at its wellhead temperature of 100.0 degF and marched again. Its gradient goes from 0.025405143 to 0.032012925 psi/ft, a change of 26.0096 percent. What has that control isolated?', '["The error in the geotherm, since holding the temperature removes the only assumed input in the march and what remains is the physics.", "Compression on its own, which raises the gradient, leaving the real column as that effect plus the opposite one.", "The truncation of the march, which shows up as a change in the gradient once the temperature is no longer varying between steps and the corrector has less work to do.", "The pressure dependence of z, which is the only term left once the temperature is frozen."]'::jsonb, 1, 'The isothermal column reaches 1243.177680881 psia instead of 1215.716705320 psia, a difference of 27.460976 psi at the packer.'),
  ('gaslift', 'beginner', 'module', 'm02-the-injection-line', 8, 'The flat 0.02 psi/ft rule of thumb misses the packer pressure by -206.539805 psi on column 2 and by 26.102397 psi on column 3. What is the lesson in the two signs?', '["That the rule is calibrated on mid range columns and the error grows with the depth of the well, changing sign once the column is deep enough to matter.", "That one of the two errors is an artefact of the differing gas gravities.", "That a flat rule has no pressure in it, so it reads low on a high pressure column and high on a low pressure one.", "That the rule always reads low, the positive sign being a reporting convention."]'::jsonb, 2, 'Each of those misses is about 48.4 percent of that column''s whole lift, in opposite directions, so the size of the error is not the surprising part.'),
  ('gaslift', 'beginner', 'module', 'm02-the-injection-line', 9, 'At surface the local gradient over 0.02 psi/ft is 1.993598 on the 1414.7 psia column and 0.680826 on the 614.7 psia one. What sets that ratio?', '["The pressure level of the column, since the gradient tracks pressure over z and temperature while the rule carries no pressure at all.", "The depth of the well, deeper columns having more room to accumulate weight.", "The gas gravity, 0.7 against 0.6, which is what the rule of thumb was calibrated on.", "The temperature at the wellhead, 110.0 degF against 90.0 degF."]'::jsonb, 0, 'Close to twice the rule on one column and about a third below it on the other is one rule of thumb meeting two ordinary injection systems.'),
  ('gaslift', 'beginner', 'module', 'm02-the-injection-line', 10, 'Marched to their packers, the three columns read 1.244654, 1.895866 and 0.667073 times the flat rule. What does that say about where the rule of thumb becomes usable?', '["The rule becomes usable below about 8000 ft, where the ratios on the two deeper columns have converged closely enough for design work.", "The rule becomes usable at the packer, which is where it was calibrated and where the ratios are furthest from their surface values on all three columns.", "There is no such depth, since the ratios move as the columns are marched without approaching one.", "The rule becomes usable once averaged over the whole column, the average gradient being the quantity the rule was written to approximate in the first place."]'::jsonb, 2, 'The engine header names the flat rule explicitly as the thing it refuses to use, rather than as an approximation it improves on.'),
  ('gaslift', 'beginner', 'module', 'm02-the-injection-line', 11, 'The column is stepped with a predictor and a trapezoidal corrector on the gradient. What does that construction buy?', '["First order behaviour, the corrector serving only to keep the march stable when the gradient changes quickly near the surface of a high pressure column.", "Second order behaviour, so each doubling of the step count cuts the remaining error by about four.", "An exact answer, because the corrector removes the truncation entirely and leaves only the rounding of the arithmetic.", "Fourth order behaviour, each doubling cutting the error by about sixteen."]'::jsonb, 1, 'The engine marches at 20 steps for spacing and valve settings and at 40 steps for the plotted injection curve, so those are the numbers a design carries.'),
  ('gaslift', 'beginner', 'module', 'm02-the-injection-line', 12, 'Two closed forms exist for the isothermal case with z pinned at 1. What separates them, and by how much?', '["The temperature convention, one form working in degF and the other in degR, which is a fixed offset in the exponent of the two expressions.", "The compressibility factor, one form pinning z at 1 and the other carrying a mean z evaluated at the average pressure of the column being marched.", "Nothing of substance, the two agreeing to every figure a design reports.", "The coefficient: the textbook form carries a rounded 0.01875 and the engine carries 0.0187417041 from its own constants, 4.4264e-4 apart in relative terms."]'::jsonb, 3, 'At 1014.7 psia, 8000 ft, 0.65 gravity and 140.0 degF they read 1193.848862916 and 1193.762984148 psia, 8.5879e-2 psi apart before a single step is taken.'),
  ('gaslift', 'beginner', 'module', 'm02-the-injection-line', 13, 'Refining the same march gives errors of 2.6688e-4, 1.0675e-5 and 1.0676e-7 psi against one reference, and -8.5612e-2, -8.5868e-2 and -8.5879e-2 psi against another. How do those two sequences differ in kind?', '["The first is truncation, which refinement removes, and the second is a mismatch between two constants, which refinement never touches.", "The first is measured at a tabulated node and the second between nodes, so the second carries a chord error on top of the march error it shares.", "The first is an absolute error and the second a relative one.", "Both are truncation, the second converging more slowly."]'::jsonb, 0, 'A residual that refuses to shrink is a signal to check what the march is being compared with, rather than a signal that the march has stopped improving.'),
  ('gaslift', 'beginner', 'module', 'm02-the-injection-line', 14, 'At 2 steps the march sits 2.0476e-2 psi from the textbook closed form and 1.0635e-1 psi from the engine constant one. Why is the smaller of those figures not the better result?', '["Because 2 steps is below the 20 step minimum the engine enforces internally.", "Because the sign of the textbook error flips between 2 and 10 steps, so the coarse march is passing through that reference on its way to the wrong side of it.", "Because the textbook reference is the one the engine actually converges onto, so any agreement with it at a coarse step count has to be luck rather than accuracy.", "Because errors at that size are dominated by floating point rounding rather than by the step count, which makes the comparison meaningless at either reference."]'::jsonb, 1, 'Against the engine''s own constant the 2 step row is the worst of the sequence, which is the reading that matches the state of the march.'),
  ('gaslift', 'beginner', 'module', 'm02-the-injection-line', 15, 'Handing each published depth pressure back to the inverse recovers the surface pressure with closures of -1.930e-10, -2.819e-10 and -2.940e-10 psi. What do those closures prove?', '["That the gradient and the compressibility factor used in the march are both correct, since an error in either would break the round trip at that precision.", "That the march has converged to the physical column.", "Only that the two directions of one routine agree, since the inverse is a secant search on the same forward march.", "That the engine constant and the textbook coefficient agree once the column is traversed in both directions, the difference cancelling on the return leg."]'::jsonb, 2, 'The return trip subtracts an error the outward trip added, so at the 40 step default column 1 goes down 1.251e-4 psi heavy and comes back -1.026e-4 psi light.'),
  ('gaslift', 'beginner', 'module', 'm03-three-lines-on-one-plot', 1, 'The kill fluid gradient is called the exchange rate between pressure and depth. Where does the module get it?', '["It is fitted from the unloading wellhead pressure and the kickoff pressure once the target depth is known.", "It is declared outright as an input, 0.45 psi/ft on westTexasOil and 0.42 psi/ft on constantPressurePPO, with no correlation producing it and no check on it.", "It is marched from surface conditions in the same way the injection column is, using the density of the completion brine at each step of the walk down the tubing.", "It is read from the flowing production traverse the caller supplies."]'::jsonb, 1, 'Everything the unloading line does is downstream of a value somebody typed, which is a limit worth stating before any of the arithmetic that follows it.'),
  ('gaslift', 'beginner', 'module', 'm03-three-lines-on-one-plot', 2, 'Across the westTexasOil string the head available falls from 703.559966806 psi to 92.707547126 psi while the kill fluid gradient never changes. What has changed?', '["The fluid itself, lighter at the deeper valves after aeration.", "The gradient of the injection column, which flattens with depth.", "The transfer differential, raised stage by stage as valves deepen.", "Only the pressure available to push the fluid, so each stage buys fewer feet than the one above it."]'::jsonb, 3, 'Nothing about the fluid differs between the top valve and the bottom one, which is why the exchange rate is constant while the depth bought collapses.'),
  ('gaslift', 'beginner', 'module', 'm03-three-lines-on-one-plot', 3, 'How does a heavier kill fluid, 0.5 psi/ft rather than 0.42 psi/ft, change a design?', '["It buys less depth for the same head at every stage, so the whole string is redrawn rather than one valve adjusted.", "It buys less depth only at the top valve, since the deeper valves are set by the transfer line.", "It buys more depth per psi, a heavier column standing higher against the gas.", "It leaves the depths alone and changes only the pressure at which each valve is set to close."]'::jsonb, 0, 'Every stage divides by the same number, so the deeper the valve the more of a late change in kill fluid gradient it inherits from the valves above it.'),
  ('gaslift', 'beginner', 'module', 'm03-three-lines-on-one-plot', 4, 'Why is it wrong to use the kill fluid gradient for the tubing while a well is unloading?', '["Because the kill fluid gradient is quoted at surface conditions and needs a temperature correction.", "Because the tubing gradient is not a straight line at all during unloading.", "Because the kill fluid gradient describes the unaerated column standing above the gas and not what the well is producing while it lifts.", "Because the kill fluid gradient already includes the weight of the injection gas."]'::jsonb, 2, 'The two are declared separately and are far apart, 0.45 against 0.1 psi/ft on westTexasOil and 0.46 against 0.09 psi/ft on midDecrementKnifeEdge.'),
  ('gaslift', 'beginner', 'module', 'm03-three-lines-on-one-plot', 5, 'What does the module admit about the unloading line being a straight line on a constant gradient?', '["That the straight line is an approximation it corrects afterwards.", "That a real unloading column is neither straight nor constant, which is why the gradient is declared as an input rather than returned as a result.", "That the straight line holds while the fluid is unaerated and fails only below the point of injection, where the tubing carries a mixture instead of a single fluid.", "That the straight line is exact for a static column of one fluid."]'::jsonb, 1, 'Declaring the gradient rather than computing it is how the module avoids being caught claiming to know something it has not been given.'),
  ('gaslift', 'beginner', 'module', 'm03-three-lines-on-one-plot', 6, 'How is the transfer pressure at a valve depth built on westTexasOil, and what does it read at 2119.249994721 ft?', '["The unloading wellhead pressure of 114.7 psia plus a declared 0.1 psi/ft, giving 326.624999472 psia.", "The kickoff pressure of 1014.7 psia less the kill fluid head above the valve, which gives the pressure the tubing shows while that valve is being uncovered.", "The injection pressure at that depth less the 50.0 psi transfer differential, the differential being what separates the two lines at every stage of the design.", "The operating pressure of 914.7 psia less the lifted gradient over the depth."]'::jsonb, 0, 'The other published cases declare their own pairs, 214.7 psia with 0.12 psi/ft, 164.7 psia with 0.08 psi/ft and 154.7 psia with 0.09 psi/ft.'),
  ('gaslift', 'beginner', 'module', 'm03-three-lines-on-one-plot', 7, 'The westTexasOil transfer line climbs at 0.1 psi/ft while the injection column runs from 0.025405143 to 0.024893071 psi/ft. What follows from that comparison?', '["The two lines run parallel once the injection column has been marched deep enough for its gradient to settle, so the gap stops closing below a certain depth.", "The injection line loses pressure with depth while the tubing side gains it, and the crossing is where the injection column has given up all of its surplus.", "The tubing side climbs more slowly than the gas, so the gap widens with depth and the string is limited by the valve count rather than by pressure.", "The two lines close on each other and must eventually meet, which is what ends a string."]'::jsonb, 3, 'The gas is not getting weaker, it gains 201.016705 psi over 8000 ft, it simply gains far less than the tubing side gains over the same interval.'),
  ('gaslift', 'beginner', 'module', 'm03-three-lines-on-one-plot', 8, 'The transfer differential is 50.0 psi on westTexasOil, 75.0 on deepHighPressure, 100.0 on constantPressurePPO and 60.0 on midDecrementKnifeEdge. What kind of quantity is it?', '["A derived quantity, set by the difference between the kill fluid gradient and the lifted gradient of each case once the wellhead pressures are known.", "A property of the valve hardware, following from the port to bellows ratio of the valves the design has been given to work with.", "A decision, chosen rather than derived, and a larger one is a safer transfer and a shallower well.", "A tolerance on the spacing recursion, which stops when depths agree."]'::jsonb, 2, 'Nothing in the module tells you which trade you wanted, and the number moves every depth in the string rather than only the valve it is applied at.'),
  ('gaslift', 'beginner', 'module', 'm03-three-lines-on-one-plot', 9, 'What goes wrong if the transfer line is read as the well''s flowing production traverse?', '["An unloading assumption has been used as a flowing answer, with no warning, since the number was never labelled a forecast.", "The two are the same curve at the point of injection and differ only above it.", "The traverse would be too heavy, because the transfer line carries the kill fluid gradient rather than the lifted one and so overstates the pressure at every depth in the tubing.", "The rate would be double counted, through the transfer line and the port."]'::jsonb, 0, 'The module has no outflow model of any kind, and the flowing traverse it needs is passed in from outside as a depth and pressure table.'),
  ('gaslift', 'beginner', 'module', 'm03-three-lines-on-one-plot', 10, 'constantPressurePPO holds 1114.7000 psia at all six of its stages and its increments still shrink, from 1826.240016740 ft to 1174.030990885 ft. What does that establish?', '["That a constant pressure design converges faster than a surface close one.", "That the transfer line rising against a nearly flat injection line is enough on its own to close the gap.", "That the surface decrement is what closes the gap, the constant pressure case being a special case where the transfer differential of 100.0 psi acts as a decrement instead.", "That the 0.42 psi/ft kill fluid buys the least depth per psi of head."]'::jsonb, 1, 'The decrement accelerates the crossing rather than causing it, which is why one convention and the other are the same recursion at different decrements.'),
  ('gaslift', 'beginner', 'module', 'm03-three-lines-on-one-plot', 11, 'deepHighPressure places 7 valves against a declared limit of 14 and stops with its deepest mandrel at 8644.662255376 ft. What stopped it?', '["The valve limit, which the published inputs set well below what the pressure would have supported on this case.", "The target depth, the string having reached the floor the design declared for it and stopped there as the deepest of the four published cases does.", "Minimum spacing, and it is still 1855.337744624 ft above its 10500.0 ft floor.", "The injection pressure, the kickoff of 1414.7 psia having been spent 40.00 psi at a time until nothing was left to place another valve with."]'::jsonb, 2, 'Not one of the four published strings exhausted its mandrels, so a string runs out of room rather than running out of valves.'),
  ('gaslift', 'beginner', 'module', 'm03-three-lines-on-one-plot', 12, 'constantPressurePPO drops from 1174.030990885 ft to 152.956208919 ft between its last two valves. Is that the recursion converging?', '["Yes, the increments approach a fixed point as the injection line and the transfer line meet, and the last one is the residual gap at the crossing.", "Yes, and the same shape appears on every published case, which is how the design signals that the deepest useful valve has been reached.", "No, it is the minimum spacing floor of 200.0 ft being enforced on the last increment of the string.", "No, it is the final mandrel being pulled to target depth, and that branch returns before the minimum spacing test runs."]'::jsonb, 3, 'The steepest looking convergence in the output violates the declared 200.0 ft minimum in silence, because no warning is raised on that path.'),
  ('gaslift', 'beginner', 'module', 'm03-three-lines-on-one-plot', 13, 'Of the three lines a design is drawn with, which has ever been priced against a reference?', '["Only the injection line, because a marched real gas column can be set beside the flat rule and the miss measured.", "All three, each against its own published golden value.", "Only the unloading line, whose kill fluid gradient can be checked against a measured density.", "None of them, since the goldens record depths rather than gradients."]'::jsonb, 0, 'The unloading and transfer gradients carry whatever error they carry silently, and nothing in the module reports a figure for either of them.'),
  ('gaslift', 'beginner', 'module', 'm03-three-lines-on-one-plot', 14, 'The flat rule of thumb misses the packer pressure by -41.016705 psi on the 1014.7 psia column, which is 20.4046 percent of that column''s lift. What is that number an example of?', '["The truncation the march carries at its default step count, which is the reason a design marches the column rather than multiplying a gradient by a depth.", "The error the unloading and transfer lines carry as well, the flat gradient being the same assumption applied to all three lines of the design.", "The cost of one flat gradient on the one line where a reference exists to price it against.", "The chord bias of the plotted injection curve, which reads low because the pressure curve is concave and a straight line under it falls short."]'::jsonb, 2, 'The same rule misses by 48.4222 percent on the 1414.7 psia column and by 48.4296 percent on the 614.7 psia one, in opposite signs.'),
  ('gaslift', 'beginner', 'module', 'm03-three-lines-on-one-plot', 15, 'A design reports valve 1 at 2119.249994721 ft. What does that precision describe?', '["The accuracy of the depth, the recursion having been iterated finely.", "The arithmetic only, since the depth inherits a 0.45 psi/ft and a 0.1 psi/ft that nothing has measured.", "The resolution of the injection pressure curve, which is tabulated finely enough to place a valve to that many decimal places.", "The agreement with the independent oracle, which matches the published depths on that case to eight ten-thousandths of a foot and so justifies reporting them at that width."]'::jsonb, 1, 'Precision in an output is a property of the arithmetic rather than of the assumptions it started from, and the two declared gradients carry no error figure at all.'),
  ('gaslift', 'beginner', 'module', 'm04-the-top-valve', 1, 'Which condition fixes the depth of valve 1?', '["The depth at which the marched injection pressure equals the unloading wellhead pressure plus the kill fluid gradient acting over that same depth.", "The depth at which the surface decrement has finally been spent.", "The depth at which the transfer line meets the lifted gradient.", "The depth at which the port can pass the design gas rate."]'::jsonb, 0, 'Both sides of that equality are pressures read at one point, which is why the unknown is a depth rather than a pressure.'),
  ('gaslift', 'beginner', 'module', 'm04-the-top-valve', 2, 'Why can the first mandrel not be placed in a single evaluation?', '["The kill fluid gradient is measured afresh at every trial depth, so the standing column has to be rebuilt from fluid properties before each pass.", "The injection pressure depends on the depth and the depth depends on the injection pressure, so the condition is circular.", "The unloading wellhead pressure stays unknown until the string has been spaced.", "The valve count has to be settled first."]'::jsonb, 1, 'The circle is broken by treating the condition as a fixed point and iterating it, which is a different technique from the secant search used to march back up.'),
  ('gaslift', 'beginner', 'module', 'm04-the-top-valve', 3, 'On westTexasOil the trial depth moves 112.559756904 ft, then 6.314981747 ft, then 0.354232178 ft. What does that pattern establish?', '["The moves shrink because the kill fluid gradient is reduced at every pass, which is what drags the trial depth back toward the weightless seed.", "The moves shrink because the march step count is doubled at every pass, so the truncation error falls by close to a factor of four each time.", "Every move is a small fraction of the one before it, so the iteration is converging and only a settled move counts as an answer.", "Only the first move is worth recording."]'::jsonb, 2, 'The last two published moves are 0.019870090 ft and 0.001114580 ft, so the sequence is still shrinking by roughly the same factor when it is stopped.'),
  ('gaslift', 'beginner', 'module', 'm04-the-top-valve', 4, 'What is wrong with reporting the weightless reach of 2000.000000000 ft as the westTexasOil first mandrel?', '["It is 119.249955500 ft too deep, because a weightless gas column overstates the head available to push the kill fluid down the tubing.", "It ignores the surface decrement of 25.00 psi per valve, which has to be taken off before the first mandrel can be placed against the kill fluid.", "It uses the lifted gradient of 0.1 psi/ft in place of the kill fluid gradient of 0.45 psi/ft, which is why it lands so far from the true depth.", "It is 119.249955500 ft too shallow, and it is a seed rather than an answer."]'::jsonb, 3, 'A mandrel set that high never recovers the depth, because every valve beneath it is spaced from the one above.'),
  ('gaslift', 'beginner', 'module', 'm04-the-top-valve', 5, 'Across the four published designs, what does the weight of the injection gas do to the first mandrel?', '["It always sends it deeper than the weightless reach, by 5.9625 percent on the 1014.7 psia system and 8.5914 percent on the 1414.7 psia one.", "It sends it deeper on the higher pressure systems and shallower on the lower pressure ones, because the sign of the gas gradient follows whether the local gradient sits above or below the flat rule of thumb.", "It moves the mandrel by a fixed 100 ft on every published case.", "It leaves the mandrel where the weightless arithmetic put it."]'::jsonb, 0, 'The direction never changes because annular gas adds pressure on the way down, and that added pressure buys depth against the kill fluid.'),
  ('gaslift', 'beginner', 'module', 'm04-the-top-valve', 6, 'Walking the westTexasOil kill fluid gradient from 0.35 to 0.6 psi/ft does what to the first mandrel?', '["It carries the mandrel from 1566.149985252 ft down to 2771.766518393 ft.", "It carries the mandrel from 2771.766518393 ft up to 1566.149985252 ft, which is further than any other single input on that well moves it.", "It leaves the mandrel within a few feet of 2119.249955500 ft.", "It moves the mandrel about as far as the gas gravity does."]'::jsonb, 1, 'Nothing inside the module computes that gradient, so the strongest lever on the string is a value somebody typed in.'),
  ('gaslift', 'beginner', 'module', 'm04-the-top-valve', 7, 'westTexasOil declares kill fluid at 0.45 psi/ft and an unloading gradient of 0.1 psi/ft. What separates the two?', '["The first is the gradient of the annular injection gas at depth and the second is that of the same gas read back at the surface manifold.", "The first applies above the point of injection and the second applies below it, so the two are read on opposite sides of the operating valve.", "The first is a measured value and the second a correlation.", "The first is the dead well before any gas has entered it, and the second is the aerated column left behind once a valve is passing gas."]'::jsonb, 3, 'At 2119.249994721 ft those two lines read 1068.362497529 psia and 326.624999472 psia, which is how far apart two straight lines in one hole can sit.'),
  ('gaslift', 'beginner', 'module', 'm04-the-top-valve', 8, 'deepHighPressure carries the heaviest kill fluid of the four published cases at 0.5 psi/ft, yet lands the deepest first mandrel. Why?', '["Its unloading wellhead pressure of 214.7 psia is the highest of the four, and a higher wellhead pressure buys depth against a heavy kill fluid.", "Its surface decrement is the smallest of the four, so more head is left over for the first mandrel before the recursion begins.", "It also carries the highest kickoff pressure, and the two inputs pull against each other.", "Its injection gas gravity is the heaviest of the four, so the annular column gains enough extra weight going down to overcome the heavier kill fluid."]'::jsonb, 2, 'constantPressurePPO makes the same point from the other side: the lightest kill fluid at 0.42 psi/ft reaches 2410.595757101 ft off a lower kickoff.'),
  ('gaslift', 'beginner', 'module', 'm04-the-top-valve', 9, 'Which design input is absent from the top valve condition altogether?', '["The surface decrement per valve, which sets every spacing below valve 1 and none of valve 1 itself.", "The unloading wellhead pressure, which enters only once the transfer line has been drawn against the injection line at the second mandrel.", "The kill fluid gradient.", "The kickoff pressure."]'::jsonb, 0, 'westTexasOil at 25.00 psi per valve and midDecrementKnifeEdge at 26.75 psi per valve both place valve 1 from kickoff, wellhead and kill fluid alone.'),
  ('gaslift', 'beginner', 'module', 'm04-the-top-valve', 10, 'How does the injection gas gravity reach the first mandrel?', '["Through the kill fluid gradient, which is scaled by the gravity at each depth.", "Purely through the weight of the injection column, and it shifts the depth only tens of feet across its whole range from 0.55 to 0.8.", "Through the surface decrement applied per valve.", "Through the transfer differential demanded at each stage."]'::jsonb, 1, 'On westTexasOil that whole range runs 2095.769374223 ft to 2162.184191942 ft, with nothing else in the design touched.'),
  ('gaslift', 'beginner', 'module', 'm04-the-top-valve', 11, 'Raising the unloading wellhead pressure on westTexasOil lifts the first mandrel. Which other input behaves the same way?', '["The kickoff pressure, because both add pressure to the annulus and so hand the design more head to spend on depth.", "The injection gas gravity, because both change the weight of the standing column the injection line marches through.", "The kill fluid gradient, because both are head the injection line must clear before it starts buying depth.", "The surface decrement per valve."]'::jsonb, 2, 'Between 64.7 and 214.7 psia the mandrel travels from 2236.962885353 ft to 1883.817105956 ft, tens of feet for each 25 psi step.'),
  ('gaslift', 'beginner', 'module', 'm04-the-top-valve', 12, 'A depth read between two tabulated samples of the injection pressure curve carries how many sources of error?', '["One, because the march error cancels exactly at any depth falling between two tabulated samples of the same column.", "Three, because the march, the straight line and the surface decrement each contribute a share of the reported pressure.", "One, because the curve is tabulated finely enough that only the straight line between samples survives.", "Two, the error of the march and the straight line drawn between samples."]'::jsonb, 3, 'On column 1 at 4 samples the reading at 4000.0 ft carries 7.1851e-3 psi of march error while the chord contributes -2.9517e-2 psi.'),
  ('gaslift', 'beginner', 'module', 'm04-the-top-valve', 13, 'Why is the chord component of an interpolated injection pressure negative in every row of every published column?', '["The local gradient falls slightly with depth, so the pressure curve is concave and a chord drawn under it sits below the curve.", "The march is biased low at every step because the trapezoidal corrector averages the gradients at both ends of the interval and the deeper end always carries the smaller of the two.", "The sample count is always an even number.", "The interpolation rounds toward the shallower sample."]'::jsonb, 0, 'Column 2 shows the same sign at a larger size, -1.4845e-1 psi at 4 samples and -6.2803e-4 psi at 64.'),
  ('gaslift', 'beginner', 'module', 'm04-the-top-valve', 14, 'At what resolutions does the engine actually run the gas column?', '["40 steps for spacing and valve settings, and 20 for the plotted injection curve, so the plot is the coarser of the two.", "20 steps for spacing and valve settings, and 40 for the plotted injection curve.", "64 steps everywhere, which is where the chord component on column 1 falls to -1.2220e-4 psi and stops mattering to a design.", "2000 steps throughout."]'::jsonb, 1, 'At those two resolutions the chord component is thousandths of a psi or smaller on systems of over a thousand psia, so it changes no spacing answer.'),
  ('gaslift', 'beginner', 'module', 'm04-the-top-valve', 15, 'westTexasOil places its first mandrel exactly where the condition says. What does that establish about the design?', '["That the string will unload without injecting at two depths at once.", "That the valve count and the stop reason follow from the first depth.", "Nothing beyond that one depth, since the same design still raises three multipointing warnings, at stages 2, 3 and 4.", "That the declared minimum spacing has been honoured."]'::jsonb, 2, 'deepHighPressure raises no multipointing warning at all and still stops on minimum spacing at 7 valves without reaching its 10500.0 ft target.'),
  ('gaslift', 'beginner', 'module', 'm05-a-column-that-converges', 1, 'What makes a single step of the annulus march second order?', '["It evaluates the compressibility factor twice, once on Sutton pseudo criticals and once with the Wichert and Aziz acid correction, and carries the mean of the two into the density.", "It squares the step length before applying the gradient.", "It predicts the pressure at the bottom of the interval from the gradient at the top, then corrects it with the average of the gradients at both ends.", "It halves the step count repeatedly and accepts the first value at which the reported pressure stops moving in the digits a spacing answer would ever print."]'::jsonb, 2, 'Second order is a claim that can be measured rather than believed, which is what the ratio column in a refinement table exists to do.'),
  ('gaslift', 'beginner', 'module', 'm05-a-column-that-converges', 2, 'Column 1 marched in one step returns 1215.911062391 psia against a golden of 1215.716705320 psia. What is that single step actually doing?', '["Losing the trapezoidal corrector, which is worth about four thousandths of a psi.", "Reporting the isothermal column instead of the geothermal one.", "Inverting the column rather than marching it, which is why it reads high.", "Evaluating the gradient at one pressure and applying it over the whole hole, which is the flat rule of thumb with extra arithmetic attached."]'::jsonb, 3, 'The 1.9436e-1 psi it is wrong by does not look absurd on a plot, and column 2 at one step is wrong by 1.4904e+0 psi in the same quiet way.'),
  ('gaslift', 'beginner', 'module', 'm05-a-column-that-converges', 3, 'The round trip on published column 1 closes to -1.930e-10 psi. What does that closure prove?', '["That the two directions of one routine agree with each other, because the inverse is a secant search on the same forward march.", "That the gradient model, the compressibility factor and the constants are all correct, since an error in any of them would open the closure at that scale.", "That the march has converged, because a residual that small sits far below the 5.0036e-4 psi spread between 20 and 2000 steps.", "That the geotherm was declared linear."]'::jsonb, 0, 'At the 40 step default the same inverse recovers 1014.699897424 psia against 1014.700000000 psia, which is the forward error coming straight back.'),
  ('gaslift', 'beginner', 'module', 'm05-a-column-that-converges', 4, 'In the refinement sequence for column 1 the error ratio sits near 4 at every doubling. What is that column reporting?', '["That the reference march at 20000 steps is itself converging, since the ratio measures the reference rather than the march under test.", "A second order method behaving exactly as its order predicts.", "That the step count has passed the point where the next digit is visible to a spacing answer or to a closing test.", "That the gradient falls by roughly a quarter over the length of the column, which the ratio inherits directly."]'::jsonb, 1, 'It is the single most informative column in the table, because a value drifting well below 4 as the steps rise would say the method was losing its order.'),
  ('gaslift', 'beginner', 'module', 'm05-a-column-that-converges', 5, 'The 5 step row on column 1 breaks the pattern with a ratio of 1.5615. Why is that not a defect?', '["5 is not a doubling of 4, so the row does not get a doubling''s worth of improvement out of the method.", "Odd step counts land the final node off the packer depth.", "The reference march was run at an even count.", "The geotherm is sampled elsewhere at 5 steps."]'::jsonb, 0, 'The same exception appears on published column 2, where the 5 step ratio is 1.5600 while every genuine doubling sits between 3.8028 and 3.9980.'),
  ('gaslift', 'beginner', 'module', 'm05-a-column-that-converges', 6, 'What would a ratio collapsing toward 1 as the steps rise be telling you?', '["That the method has gained an order, since a smaller ratio means each doubling is removing a larger share of what is left over.", "That the remaining error has stopped being truncation and become something else.", "That the column has become isothermal.", "That the step length has fallen below a foot."]'::jsonb, 1, 'That is the diagnostic behind the whole module: the shape of the sequence, not the size of any one residual, says what kind of error you are holding.'),
  ('gaslift', 'beginner', 'module', 'm05-a-column-that-converges', 7, 'How do the numerical and the modelling errors available on this column compare in size?', '["They sit within the same order of magnitude, so a step count chosen carelessly can cost as much as a gradient model chosen carelessly on the same column, which is why one of the two is never enough to report.", "The march dominates, since 3.5210e-3 psi at the deepHighPressure packer is the largest single error anywhere in the module''s published blocks, and larger than anything the declared gradient model contributes.", "The march contributes thousandths of a psi at 20 steps while the flat rule of thumb contributes hundreds, and refinement reaches only the first of the two.", "Neither can be measured without a field pressure survey."]'::jsonb, 2, 'No amount of refinement reaches -206.539805 psi at 11000 ft on column 2 or 26.102397 psi at 4000 ft on column 3.'),
  ('gaslift', 'beginner', 'module', 'm05-a-column-that-converges', 8, 'One flat rule reads low against a high pressure column and high against a low pressure one. Which property of a column decides that sign?', '["Its depth, since a longer column gives the compression room to run ahead of the geotherm before the packer is reached.", "Its temperature range, since a wider geotherm drives the local gradient down through the flat rule on the way to the packer.", "Its gas gravity, since a heavier gas raises the density everywhere and pushes the whole column onto one side of the rule of thumb.", "Its pressure level, since the rule carries no pressure in it at all."]'::jsonb, 3, 'The two misses are 48.4222 percent and 48.4296 percent of their columns'' lifts, which is why no correction factor repairs the rule.'),
  ('gaslift', 'beginner', 'module', 'm05-a-column-that-converges', 9, 'What does holding a column at its wellhead temperature isolate?', '["The truncation of the march, since temperature is what the step count resolves.", "The compression acting on its own, so the gradient on column 1 rises by 26.0096 percent instead of falling, and the two competing effects can be told apart.", "The chord under the plotted curve, which flattens once the geotherm is removed.", "The gap between the textbook coefficient and the engine''s own constant."]'::jsonb, 1, 'That control puts the isothermal column at 1243.177680881 psia, which is 27.460976 psi above the same column marched with its geotherm in place.'),
  ('gaslift', 'beginner', 'module', 'm05-a-column-that-converges', 10, 'One march at rising step counts is run against three references and behaves three ways. What differs between the three?', '["Only the references, since the marched pressures themselves are identical in all three columns.", "The step schedule, since each reference demands a different sequence of counts before its residual can be read fairly.", "The gas gravity used in each march.", "The depth at which each is read."]'::jsonb, 0, 'Change the reference alone and the same march reports 1.0676e-7 psi or -8.5879e-2 psi, which is why a residual has to be quoted with what it was measured against.'),
  ('gaslift', 'beginner', 'module', 'm05-a-column-that-converges', 11, 'A residual that refuses to shrink under refinement is telling you what?', '["That the method has lost its order, so the truncation is no longer falling by a factor near 4 at every doubling.", "That the step count has already reached the point where further refinement is invisible to anything downstream of the column.", "That the march is unstable at that resolution.", "That two different things are being compared, and the job is to find which two."]'::jsonb, 3, 'It is not evidence that the method is bad, and reading it that way is how a genuinely sound march gets reported as a defect.'),
  ('gaslift', 'beginner', 'module', 'm05-a-column-that-converges', 12, 'What was the parked residual of -8.5879e-2 psi eventually traced to?', '["A geotherm held linear in the march and constant in the closed form, which leaves a fixed offset no step count can remove.", "A compressibility factor pinned at 1 in the march while the closed form carried the Dranchuk and Abou-Kassem value.", "One constant written two ways, agreeing to four significant figures and no further.", "A depth of 8000 ft in the march against a reference evaluated at the shallower of two tabulated samples."]'::jsonb, 2, 'The textbook coefficient is 0.0187500000 and the engine carries AIR_MW over 144 R at 0.0187417041, lower by 4.4264e-4 relative.'),
  ('gaslift', 'beginner', 'module', 'm05-a-column-that-converges', 13, 'The coarsest row of the refinement table is the best row against one reference and the worst against the other. What mechanism produces that?', '["The coarse march still carries a large truncation error and it happens to cancel part of the constant offset, so one reference flatters the row while the other measures it undiluted.", "The two references are read at different depths, so only one of them ever sees the truncation.", "The engine constant is the larger of the two, so every residual measured against it comes out larger.", "The 2 step march is the only row where the corrector is skipped, which inflates one residual and not the other."]'::jsonb, 0, 'At 2 steps the two residuals read 2.0476e-2 psi and 1.0635e-1 psi, and the smaller of them keeps shrinking only until the sign flips somewhere before 10 steps.'),
  ('gaslift', 'beginner', 'module', 'm05-a-column-that-converges', 14, 'Why could the first version of this convergence check never have failed?', '["It ran only at 2000 steps, where the truncation is already below the resolution at which a residual can be printed for either reference.", "It printed the textbook form alone, watched a fixed constant mismatch sit still and called that convergence.", "It compared the march with itself at two step counts.", "It reported a round trip closure rather than a residual."]'::jsonb, 1, 'A gate whose reference carries a fixed offset measures the offset, so it looks gated while testing nothing, which is the same failure shape as coverage that is not coverage.'),
  ('gaslift', 'beginner', 'module', 'm05-a-column-that-converges', 15, 'A programme that only ever reports defects teaches a particular error. Which one?', '["That a residual falling by a factor near 4 at each doubling is evidence of a defect rather than of a method behaving as its order predicts.", "That a check reporting no defect can be skipped next time, because the same measurement gives the same empty result on any column.", "That every numerical method is suspect, which leaves you refining without ever learning which case you are in.", "That a flat rule of thumb is safer than a marched column."]'::jsonb, 2, 'Saying this column is sound cost the same measurement a defect would have cost, and it is worth something only because that measurement would have caught one.'),
  ('gaslift', 'beginner', 'module', 'm06-the-associate-reading', 1, 'Working a column in order, what must be settled before any pressure is computed?', '["The kill fluid gradient, the lifted gradient and the transfer differential, since every pressure in a design is measured against those three.", "The gas gravity, the wellhead and bottom temperatures, and the reference depth the geotherm runs linear over.", "The step count of the march and the sample count of the plotted curve, because both fix the resolution that every later reading inherits.", "The number of valves the string allows."]'::jsonb, 1, 'Those four fix every gradient in advance, and sg 0.65 with 100.0 degF at surface and 190.0 degF at 8000.0 ft is one complete specification of them.'),
  ('gaslift', 'beginner', 'module', 'm06-the-associate-reading', 2, 'Setting a column''s average gradient beside the flat 0.02 psi/ft rule, what should you expect to see?', '["A match to three figures once the column has been marched at 40 steps.", "A ratio approaching one as the column is marched deeper.", "A ratio rather than a match, and one far outside the 0.680826 to 1.993598 spread means an input is wrong rather than the march.", "A ratio below one on every column carrying an ordinary geotherm."]'::jsonb, 2, 'The three published columns average 0.025127088, 0.038776346 and 0.013474401 psi/ft, so the sanity check is a range and never a target.'),
  ('gaslift', 'beginner', 'module', 'm06-the-associate-reading', 3, 'A doubling of the step count fails to cut the remaining difference by close to 4. What does that call for?', '["Doubling again, since the ratio settles only once the step count runs well past the 40 the plotted curve is tabulated at.", "Reporting the coarser of the two answers.", "Switching the reference to the textbook closed form.", "Stopping, because nothing downstream of the column is safe until the shape of that sequence is understood."]'::jsonb, 3, 'A ratio drifting well below 4 says the method is losing its order, and one collapsing toward 1 says the error has stopped being truncation.'),
  ('gaslift', 'beginner', 'module', 'm06-the-associate-reading', 4, 'Nothing in the output says whether a depth landed on a tabulated sample or between two. What does that leave to the reader?', '["Knowing which of the two errors is being held, since only one pressure comes back.", "Nothing, because the curve carries a flag beside every interpolated value and marks the samples it was marched at.", "Choosing a sample count that divides the target depth exactly, which is the only case in which the chord vanishes.", "Reading the value twice and averaging, since the chord error changes sign either side of a tabulated sample."]'::jsonb, 0, 'Smoothness on screen comes from the plotting rather than the sampling, so a coarse curve looks exactly like a fine one.'),
  ('gaslift', 'beginner', 'module', 'm06-the-associate-reading', 5, 'Solving the first mandrel as a fixed point, what should be watched?', '["The trial depths rather than the moves, because a depth that settles in its first three figures is the signal that the condition has been met and the depth can be reported.", "The moves rather than the depths, because a move that stops shrinking by roughly the same factor each pass means the iteration is not converging.", "The injection pressure at each trial depth, since it is the quantity the condition equates and the depth is only a by product read off at the end of each pass.", "The seed, which sets the accuracy of everything after it."]'::jsonb, 1, 'On westTexasOil the moves run 112.559756904, 6.314981747, 0.354232178, 0.019870090 and 0.001114580 ft, each a small fraction of the one before it.'),
  ('gaslift', 'beginner', 'module', 'm06-the-associate-reading', 6, 'What closes the loop on a top valve depth once the fixed point has stopped?', '["Checking that the depth exceeds the weightless reach by between 5 and 9 percent.", "Checking that the surface decrement has not yet been spent.", "Checking that the injection pressure at depth equals the unloading wellhead pressure plus the kill fluid gradient over that depth, since disagreement means the iteration stopped early.", "Checking the round trip closure of the march at that depth."]'::jsonb, 2, 'westTexasOil reads 1068.362497529 psia at 2119.249994721 ft against 114.7 psia and 0.45 psi/ft, which is the same equality the depth was solved from.'),
  ('gaslift', 'beginner', 'module', 'm06-the-associate-reading', 7, 'A designer wants the first mandrel deeper and reaches for the surface decrement. What happens?', '["Every mandrel below valve 1 is reshuffled and valve 1 itself moves by 0.000000000 ft.", "Valve 1 goes deeper in step with the decrement, and the valves below hold their spacing because each is measured from the one above it.", "The valve count is held while every depth moves.", "Nothing moves until the kill fluid is revised."]'::jsonb, 0, 'It is the worst kind of adjustment, visible everywhere except where it was aimed, and the levers that do work are kickoff, kill fluid and wellhead pressure.'),
  ('gaslift', 'beginner', 'module', 'm06-the-associate-reading', 8, 'What is wrong with the weightless reach as a quoted answer?', '["It is a seed, and on westTexasOil it is 119.249955500 ft too deep, because the weight of the gas has been counted twice in it.", "It is exact for a weightless gas and therefore conservative, which is the right way to be wrong in a spacing decision.", "It is the converged answer for the lowest pressure of the four published cases and an estimate for the other three.", "It is a seed, and on westTexasOil it is 119.249955500 ft too shallow."]'::jsonb, 3, 'A mandrel set that high never recovers the depth, because every valve beneath it is spaced from the one above.'),
  ('gaslift', 'beginner', 'module', 'm06-the-associate-reading', 9, 'Which unit convention does the tier hold to throughout?', '["psig rather than psia, since a surface injection pressure is read on a gauge and every published kickoff is quoted that way.", "psia rather than psig, with Mscf/d, ft TVD, degF, psi/ft, in and lbm/ft3.", "Either psia or psig so long as the choice is declared once, because the difference cancels in a pressure balance.", "SI units, converted at the door."]'::jsonb, 1, 'Mixed units are listed beside the weightless seed and the flat rule of thumb as one of the traps a capstone run has to avoid.'),
  ('gaslift', 'beginner', 'module', 'm06-the-associate-reading', 10, 'Which inputs fix the first mandrel, and in what order of authority?', '["Surface decrement, kickoff pressure, kill fluid gradient and transfer differential.", "Kill fluid gradient, design gas rate, port size and wellhead pressure.", "Kickoff pressure, kill fluid gradient, wellhead pressure and gas gravity, with the first two worth hundreds of feet and the last two worth tens.", "Wellhead pressure, minimum spacing, valve count limit and gas gravity."]'::jsonb, 2, 'The four published designs land their first mandrel at 2119.249955500, 2606.192537300, 2410.595626808 and 2354.019550242 ft on those inputs alone.'),
  ('gaslift', 'beginner', 'module', 'm06-the-associate-reading', 11, 'What did measuring the 5.0036e-4 psi spread between 20 and 2000 steps actually buy?', '["A finding that this column carries no truncation problem, from the same measurement that would have exposed one.", "A case for raising the engine''s spacing resolution above 20 steps, since the spread is larger than the closing margins a design turns on.", "A confirmation that the declared gradients are sound.", "A tolerance to quote beside every valve depth."]'::jsonb, 0, 'That spread is 2.4891e-6 of the 201.0167 psi the column lifts, and the error ratio near 4.0 in every block says the order is intact.'),
  ('gaslift', 'beginner', 'module', 'm06-the-associate-reading', 12, 'The chord under the plotted injection curve is -1.2220e-4 psi at 64 samples on column 1. How should a design read that?', '["As negative and large enough to matter, since valve depths converge to 0.01 ft and a closing test turns on fractions of a psi.", "As positive at fine sample counts and negative at coarse ones, so the sign has to be checked at whatever count was used.", "As the dominant error in the module, since it is larger than the difference between 20 and 2000 steps at a packer.", "As negative and far too small to reach any spacing answer."]'::jsonb, 3, 'The same chord is -2.9517e-2 psi at 4 samples on that column, which is why the sample count and not the sign is what has to be watched.'),
  ('gaslift', 'beginner', 'module', 'm06-the-associate-reading', 13, 'What does treating the injection gas as weightless at a valve depth cost, and which way does it err?', '["It throws away the whole lift, 426.539804 psi on the 1414.7 psia column, and it always errs toward a shallower and more pessimistic string.", "It throws away the kill fluid gradient and errs toward a deeper string every time.", "It costs nothing at the top valve and errs only below it.", "It throws away 201.016705 psi and errs whichever way the geotherm runs."]'::jsonb, 0, 'Because the error never changes sign it never announces itself, it simply produces a design that stops higher than it needed to.'),
  ('gaslift', 'beginner', 'module', 'm06-the-associate-reading', 14, 'Which habit does the tier hand on to the valve work that follows?', '["Round trip and close, which separates a sound implementation from a broken one by handing the answer back to the routine that produced it.", "Refine and watch, which separates a truncation falling by a factor near 4 from a residual parked at -8.5879e-2 psi.", "Quote every depth to nine decimal places.", "Prefer the coarser resolution when in doubt."]'::jsonb, 1, 'It is the same move as holding a column at its wellhead temperature: hold one thing still and the explanation doing the work shows itself.'),
  ('gaslift', 'beginner', 'module', 'm06-the-associate-reading', 15, 'What does the Associate tier leave unanswered?', '["Where the top valve goes, which needs the recursion of the following tier before a depth can be quoted.", "How the annular pressure behaves at depth, which the tier can only bound between the flat rule of thumb and a single marched column.", "Where the second valve goes, what any valve is set to, and whether the string will multipoint.", "The direction the gas gradient moves with depth."]'::jsonb, 2, 'The column is a ruler and it does not design, which is why the tier ends able to read a pressure at a depth and place one mandrel.'),
  ('gaslift', 'beginner', 'final', null, 1, 'A production supervisor raises the design gas rate from 500.0 Mscf/d to 800.0 Mscf/d and finds the casing pressure unchanged at every depth. What has happened?', '["Rate is not an input to the annular column at all, so it reaches a design only through the port that has to pass it.", "The extra gas is absorbed by the compressibility factor, which falls as throughput rises and holds the density of the column steady all the way to the packer.", "Both rates sit above the target of the smallest port in the catalogue, so the engine returns the same column for each of them and warns on neither of the two runs.", "The march was run at 20 steps, too coarse to see it."]'::jsonb, 0, 'The published cases carry design rates of 500.0, 250.0, 800.0 and 600.0 Mscf/d, and not one of those numbers touches the casing pressure at depth.'),
  ('gaslift', 'beginner', 'final', null, 2, 'A well is killed with heavier brine before a workover and the old gas lift paperwork is handed back unchanged. Walking westTexasOil from 0.45 to 0.5 psi/ft, what has that paperwork stopped describing?', '["The valve count, which a heavier standing column raises while the depths hold.", "The injection column, since a heavier standing fluid loads the annulus behind it.", "The first mandrel, which travels from 2119.249955500 ft to 1896.053564327 ft, and with it every spacing increment measured downward from that origin.", "Nothing yet, because kill fluid enters the arithmetic below the first mandrel."]'::jsonb, 2, 'Across the full sweep from 0.35 to 0.6 psi/ft that same mandrel travels from 2771.766518393 ft to 1566.149985252 ft, further than any other single input moves it.'),
  ('gaslift', 'beginner', 'final', null, 3, 'A run finishes with three warnings, every one of them about multipointing, and none about spacing. What may be concluded about the deepest mandrel?', '["That it cleared the declared 250.0 ft minimum, since a violation of a limit the case declares for itself is precisely the class of thing this engine raises a warning about.", "Nothing, because the branch that pulls a last mandrel to target depth returns before the spacing test is ever reached.", "That the string stopped on minimum spacing, which is why no separate warning was needed.", "That an independent oracle checked the increment and found nothing to report."]'::jsonb, 1, 'That mandrel lands 131.375432376 ft from its neighbour against a stated 250.0 ft minimum, and the goldens record it without complaint because the oracle mirrors the same branch ordering.'),
  ('gaslift', 'beginner', 'final', null, 4, 'An intermittent candidate is handed a string sized by this module, with a proposal to halve the declared lifted gradient so it represents a slug. Why does that not rescue the output?', '["The engine refuses a lifted gradient under 0.08 psi/ft, which is the smallest value any of the four published cases declares for itself.", "Halving that gradient doubles the transfer differential, and the string would then fail its own closing test at every stage below the first.", "The lifted gradient reaches only the top valve condition, so halving it leaves every mandrel under valve 1 exactly where the recursion put it.", "A cycling tubing column has no single lifted gradient to declare."]'::jsonb, 3, 'Spacing, valve settings and the unloading warnings all rest on a steady point of injection, so the answer to a cycling well is a different tool rather than a reinterpreted number.'),
  ('gaslift', 'beginner', 'final', null, 5, 'Valve 1 on westTexasOil is credited with 1359.548505991 Mscf/d against a 500.0 Mscf/d target, and a reviewer reads that as a safety factor near three. What is wrong with the reading?', '["The target is quoted at surface and the throughput at depth, so the two sit at different conditions and cannot be divided by one another in the first place.", "That valve runs subcritical at its stage, where the equation does not hold.", "Thornhill and Craver is an orifice equation, so the figure is a ceiling on what the port could pass and never a prediction of what the valve does.", "The throughput belongs to the 0.5 in port rather than the 0.25 in one fitted."]'::jsonb, 2, 'A real gas lift valve throttles on its stem long before it is fully open, which an orifice equation knows nothing about.'),
  ('gaslift', 'beginner', 'final', null, 6, 'Asked why a 7500.0 ft design needs eight mandrels when the first bite of gas reaches 2000.000000000 ft, what is the answer?', '["Each valve hands the well to a depth the one above it has just made reachable.", "Eight are carried because the declared limit is 12 and a design fills most of what it declares, keeping a margin in the tubing for a later workover.", "The first bite is quoted on weightless gas, and the eight mandrels are the successive corrections the weight of the injection column then requires.", "Because target depth divided by the declared minimum spacing comes to eight."]'::jsonb, 0, 'The published strings carry 8, 7, 6 and 7 valves against limits of 12, 14, 10 and 12, so not one of them ran out of mandrels.'),
  ('gaslift', 'beginner', 'final', null, 7, 'A design unloads cleanly on paper all the way to its target depth. What has that established about the barrels the well will make?', '["That the well makes at least what the 500.0 Mscf/d design rate was chosen to lift, since that target is what the port selection had to clear at every stage.", "That flowing bottomhole pressure sits under reservoir pressure at the deepest point of injection the finished string managed to reach.", "That production follows once the transfer line is swapped for the flowing traverse the module already carries internally for the crossing.", "Nothing at all, because no inflow relation exists anywhere in the module."]'::jsonb, 3, 'Unloading on paper and making oil are separate questions, and only one of the two is asked here.'),
  ('gaslift', 'beginner', 'final', null, 8, 'Two strings are drawn with a flat 0.02 psi/ft injection line, one on a 1414.7 psia system and one on a 614.7 psia system. Which way does each of the two err?', '["Both come out shallow, since a flat rule always understates a real gas column.", "The high pressure string comes out too shallow, because the flat line reads low by 206.539805 psi at its packer, and the low pressure string comes out too deep, because the flat line reads high by 26.102397 psi at its own.", "Both come out deep, because the rule leaves the compressibility factor out.", "Neither errs on depth, since a flat gradient shifts a line without tilting it."]'::jsonb, 1, 'Those two misses are 48.4222 and 48.4296 percent of the respective column lifts, so their size is comparable and only the sign separates them.'),
  ('gaslift', 'beginner', 'final', null, 9, 'Two effects pull on the same gradient and a plausible story has named only one of them. What move settles which effect is winning?', '["Compare the local gradient at surface against the flat 0.02 psi/ft rule, since the ratio at that one depth reports which of the two effects the column is being carried by.", "March the same column at a far finer step count and read the residual.", "Invert the column and check that the round trip closes on itself.", "Run the column again with temperature held at its wellhead value, which leaves compression on its own and prints the difference."]'::jsonb, 3, 'On column 1 that control moves the packer pressure by 27.460976 psi and turns a fall of 2.0156 percent into a rise of 26.0096 percent.'),
  ('gaslift', 'beginner', 'final', null, 10, 'A sour injection stream is run through a design with the Wichert and Aziz correction switched off. Which way does the finished string move, and for what reason?', '["Shallower, since omitting the correction leaves the pseudo critical pressure at 656.525000 psia and a higher pseudo critical pressure lightens the column throughout.", "Nowhere, since that correction is applied to the nitrogen dome charge and never to the injection gas the annulus is actually carrying downward.", "Deeper, since z drops from 0.849475579 to 0.821584635 and a lower z is a heavier gas at every step of the march.", "Deeper by a fixed offset at the wellhead alone, since the correction shifts surface pressure and the march then carries one offset unchanged."]'::jsonb, 2, 'On a 0.75 gravity gas at 2000.0 psia and 160.0 degF carrying CO2 at 0.08 and H2S at 0.04 the shift is an epsilon of 16.765703 degR on the pseudo criticals, compounding down the march.'),
  ('gaslift', 'beginner', 'final', null, 11, 'A validation report leads with a round trip closure of -1.930e-10 psi. What should a reviewer ask to see beside it?', '["A comparison against something outside the routine, such as the isothermal closed form the same march can be held to.", "The same closure recomputed at the 40 step default, where the engine recovers 1014.699897424 psia and the pairing of the two directions can be inspected properly.", "The step refinement sequence, whose error ratio near 4 at every doubling is the only evidence that a round trip has genuinely been carried out at all.", "The oracle depth difference of 8.030e-4 ft on the same case."]'::jsonb, 0, 'A closure that small cannot detect a wrong gradient, a wrong compressibility factor or a wrong constant, because each would be applied identically in both directions.'),
  ('gaslift', 'beginner', 'final', null, 12, 'A gradient of 0.031855542 psi/ft is lifted from a published table at 1500.0 psia and 180.0 degF and multiplied by depth. What has been assumed?', '["That one point on a surface of pressure and temperature stands for a whole column, when the same gas reads 0.011670185 psi/ft at 500.0 psia and 100.0 degF.", "That the compressibility factor is fixed at the value it takes at that pressure, which is the one assumption the march was written to avoid making anywhere in an annulus.", "That the column is isothermal, which its geotherm rules out.", "That the gas gravity of 0.65 holds unchanged all the way down."]'::jsonb, 0, 'Multiplying a point gradient by a depth is the one step march, which on column 1 returns 1215.911062391 psia against a golden of 1215.716705320 psia.'),
  ('gaslift', 'beginner', 'final', null, 13, 'A design''s spacing pressures and its plotted injection curve disagree in the fifth decimal on one and the same well. Where does that come from?', '["The plotted curve is drawn from the inverse march and not the forward one.", "Spacing and valve settings march at 20 steps while the plotted curve is tabulated at 40, so the two carry different truncation errors of the same march.", "The spacing loop stops at a tolerance of 0.01 ft while the curve does not.", "The curve carries the operating pressure and spacing the kickoff pressure."]'::jsonb, 1, 'Nothing else in the module changes the step count, so 20 and 40 are the two resolutions a real design carries.'),
  ('gaslift', 'beginner', 'final', null, 14, 'Told that compression alone decides how heavy an injection stream gets, a reviewer looks at a compressibility factor climbing from 0.817110097 to 0.910514014. What has been found?', '["It raises density at every step, because a compressibility factor nearer unity means the gas is behaving ideally and an ideal gas is the heavier of the two.", "It has no effect on the gradient, because the march divides by z turning pressure into density and then multiplies by it again when stepping the column.", "It leaves the gas lighter than compression alone would, since density goes as pressure over z and temperature.", "It pushes the local gradient upward, alongside the geotherm."]'::jsonb, 2, 'That column starts the deepest into non ideal behaviour of the three and recovers the most over its length.'),
  ('gaslift', 'beginner', 'final', null, 15, 'Halfway through a design the kill fluid gradient is revised upward. Which parts of the string have to be redrawn?', '["Only valves under the deepest mandrel that already cleared minimum spacing.", "Only the top valve, since the kill column is displaced once gas passes it.", "Only the transfer line, which stands on that same declared fluid.", "All of it, because the first mandrel is set by that gradient and every increment under it is measured from the valve above."]'::jsonb, 3, 'A revised kill fluid gradient does not adjust a string, it redraws it, and the deeper a valve sits the more of the change it inherits.'),
  ('gaslift', 'beginner', 'final', null, 16, 'A reviewer asks for the transfer differential to be raised from 50.0 psi to 100.0 psi. What is being bought, and what is being spent?', '["A deeper string, because the differential is added to the injection line before a crossing is located and a larger injection line reaches further down the hole.", "A safer transfer at every stage, paid for in depth, since the margin comes off the head that buys the next increment.", "Nothing measurable, because the differential cancels out of the recursion.", "A larger valve count, with every published depth left where it was."]'::jsonb, 1, 'The published cases declare 50.0, 75.0, 100.0 and 60.0 psi, and nothing in the engine will say which of the two trades was wanted.'),
  ('gaslift', 'beginner', 'final', null, 17, 'A reviewer asks for an error figure against each of the three lines a design is drawn with. How many can be supplied?', '["Three, since the flat 0.02 psi/ft rule prices the injection line while the two declared gradients are priced by the oracle that cut the goldens.", "Two, the injection and the unloading lines, since a kill fluid gradient is checked against the standing column the design starts out from.", "One, the injection line, which has a marched column to be priced against.", "None, since all three are straight lines drawn on a plot and a straight line carries no error at all until a depth is read off it."]'::jsonb, 2, 'Precision in an output is a property of the arithmetic and not of the assumption it started from, which is why valve 1 is reported to nine decimal places either way.'),
  ('gaslift', 'beginner', 'final', null, 18, 'Hoping to keep the increments from shrinking, a designer holds the surface injection pressure constant at every stage. What comes back?', '["Increments that shrink regardless, from 1826.240016740 ft to 1174.030990885 ft on the published constant pressure case.", "A string of even increments, which is what the constant pressure convention exists to produce and why it carries a transfer differential of 100.0 psi to hold them apart.", "A recursion that never terminates, since with no decrement the head at each stage repeats and the string walks to target depth one mandrel at a time.", "A single valve, because the crossing then never arrives at all."]'::jsonb, 0, 'The decrement accelerates the crossing rather than causing it: a transfer line rising against a nearly flat injection line is enough on its own.'),
  ('gaslift', 'beginner', 'final', null, 19, 'The transfer pressures at the published valve depths are lifted straight into a production forecast. What has been done?', '["A flowing traverse has been read at the wrong depths, since the transfer line is tabulated at the mandrels while a forecast needs it at the point of injection.", "An unloading assumption has been used as a flowing answer, with nothing anywhere to flag it.", "A gradient of 0.1 psi/ft has been used where the module already carries a validated multiphase traverse for the same well.", "A pressure in psia has been carried into arithmetic that expected psig."]'::jsonb, 1, 'The module has no outflow model at all, and the traverse it needs for the deepest injection point is passed in from outside as a depth and pressure table.'),
  ('gaslift', 'beginner', 'final', null, 20, 'A string stops three valves short of its declared limit and the response is to specify more mandrels. What will the extra mandrels achieve?', '["They reach target depth once the minimum spacing is relaxed to suit them.", "They deepen the string in proportion to the last increment achieved.", "They are placed, but every one of them below the packer depth.", "Nothing, because the string stopped where the injection line could no longer beat the transfer pressure by the declared differential, and not because it had run out of places to hang a valve."]'::jsonb, 3, 'The four published strings carry 8, 7, 6 and 7 valves against declared limits of 12, 14, 10 and 12.'),
  ('gaslift', 'beginner', 'final', null, 21, 'Where a well kicks off at only 614.7 psia, someone sketches its gas column as a rule of thumb slope and takes the crossing straight off that sketch. What has shifted?', '["Deeper, because the flat line reads high on that column, by 26.102397 psi at 4000 ft.", "Shallower, because a rule of thumb is chosen to be conservative and a conservative injection line always crosses the transfer line above the true point.", "It stays put, because the crossing is fixed by the transfer differential while a flat line changes only the pressure reported at that crossing depth.", "Deeper, because a flat line cannot be concave and a chord under it reads low."]'::jsonb, 0, 'On the 1414.7 psia column the same flat line reads low by 206.539805 psi, so the identical substitution moves the crossing the other way.'),
  ('gaslift', 'beginner', 'final', null, 22, 'Reasoning that gas compresses on the way down, a designer assumes the injection gradient rises with depth and places the first mandrel on that basis. Which way is the placement wrong, and what settles it?', '["Too shallow, because a rising gradient understates the pressure at depth.", "Not wrong, since that direction holds on all three published columns.", "Too deep, because an overstated injection pressure at depth pushes the crossing with the kill fluid column downward, and the isothermal control settles it by showing the geotherm outrunning the compression.", "Wrong only under the packer, where a geotherm stops running linear."]'::jsonb, 2, 'Holding column 1 at its wellhead temperature turns a fall of 2.0156 percent into a rise of 26.0096 percent and lifts the packer pressure by 27.460976 psi, which is the mechanism the story named alone.'),
  ('gaslift', 'beginner', 'final', null, 23, 'The fixed point for the first mandrel is stopped once a move falls under 10 ft, leaving 2118.874738652 ft on the sheet. What has that saved, and what has it cost?', '["It saved nothing, because that fixed point is evaluated as a closed expression once the weightless seed is known and no iteration is carried out after the first pass.", "Three cheap iterations saved, against a depth the remaining moves of 0.354232178, 0.019870090 and 0.001114580 ft were still going to correct.", "It cost the minimum spacing check on valve 2, which is seeded from the top valve depth and cannot run until that depth has settled to the engine''s own tolerance.", "Nothing on either count, since the recursion reseeds from target depth."]'::jsonb, 1, 'Every move is a small fraction of the one before it, so a move looking settled beside a seed of 2000.000000000 ft is no evidence that the iteration has finished.'),
  ('gaslift', 'beginner', 'final', null, 24, 'The compressor is uprated and the kickoff pressure available goes from 964.7 psia to 1064.7 psia. What does the new run show?', '["The first mandrel unchanged and the valve count raised, because kickoff pressure enters the recursion only through the decremented surface pressure at later stages.", "The first mandrel deepening from 1994.978008731 ft to 2244.400016098 ft, and every depth under it starting from somewhere new.", "A deeper string on the same top valve, valve 1 being a fixed point.", "No change at all until the operating pressure is raised to match."]'::jsonb, 1, 'Kickoff pressure and kill fluid gradient pull against one another, the one buying depth and the other spending it.'),
  ('gaslift', 'beginner', 'final', null, 25, 'Told the first mandrel is too shallow, an engineer proposes a larger surface decrement. What does the rerun report?', '["Valve 1 deepened in proportion to the decrement, because the surface pressure at its own stage is the kickoff pressure less one decrement.", "Valve 1 deepened with the valve count held, because the recursion compensates for a larger decrement by shortening each increment in turn.", "Valve 1 unchanged and the string unchanged, because a decrement reaches only the closing test and never reaches the spacing at all.", "Valve 1 shifted by 0.000000000 ft, with the count and every depth under it changed."]'::jsonb, 3, 'westTexasOil at 25.00, 27.50 and 35.00 psi per valve places 8, 7 and 6 valves and puts the first mandrel in the same place all three times.'),
  ('gaslift', 'beginner', 'final', null, 26, 'A mandrel decision is taken off an injection curve tabulated at 4 samples, at a depth falling between two of them. What is carried into the decision?', '["A reading low by the chord, running to -2.9517e-2 psi at that resolution with nothing on the curve to flag it.", "A reading high by the chord, because a straight line between two samples of a column whose pressure rises with depth always sits above the marched curve.", "A reading carrying march truncation only, because interpolating between two samples of one march introduces no error of its own at any resolution.", "A reading that is exact, since 4 samples still bracket the depth."]'::jsonb, 0, 'Smoothness on a plot comes from the plotting rather than the sampling, and at 4 samples the worst deviation anywhere on that column is -3.6727e-2 psi at 960.0 ft.'),
  ('gaslift', 'beginner', 'final', null, 27, 'A trainee expects the well standing on the densest brine to put its top mandrel highest of any in the set, and finds it placed lowest instead. Which reading has gone wrong?', '["That a heavier kill fluid deepens a top valve, the standing column being what the injection line must overcome and a heavier one being overcome lower down.", "That the unloading wellhead pressure was the deciding input on that case.", "That its minimum spacing seed placed it, being the case that stops there.", "That kickoff pressure and kill fluid gradient pull against each other, so neither input decides a depth on its own."]'::jsonb, 3, 'The lightest kill fluid of the four, at 0.42 psi/ft, reaches 2410.595757101 ft off a lower kickoff pressure than that case carries.'),
  ('gaslift', 'beginner', 'final', null, 28, 'A supply change swaps 0.65 gravity injection gas for 0.8 gravity gas, with nothing else on the well touched. What moves?', '["The first mandrel deepens from 2119.249955500 ft to 2162.184191942 ft, purely through the added weight of the injection column.", "Nothing, since gravity enters valve settings and not the spacing.", "The mandrel comes up, a heavier gas being a heavier standing load.", "The valve count alone, the depths held in place by the fixed point."]'::jsonb, 0, 'Across the whole sweep from 0.55 to 0.8 that mandrel moves tens of feet, an order below what the kill fluid gradient moves it.'),
  ('gaslift', 'beginner', 'final', null, 29, 'An engineer doubles the step count twice over and the residual does not move. Name the two candidate explanations, and the test that separates them.', '["Either the tolerance has been reached or the machine precision has, and the way to tell is to rerun that march far coarser and check the residual grows back by the factor its order predicts.", "Either the geotherm or the gas gravity is wrong, and a sweep on each settles it.", "Either the method has stopped converging or the reference is a different formulation, and refining once more while changing only the reference says which.", "Either the column is isothermal or the reference is, and the control settles it."]'::jsonb, 2, 'Change the reference alone and the same march reports 1.0676e-7 psi or -8.5879e-2 psi, and the marched pressures behind those two figures are identical.'),
  ('gaslift', 'beginner', 'final', null, 30, 'Validating on a single step count, a reader finds 2 steps closest to the textbook closed form and adopts that march. What has the reader chosen?', '["The best row on both references, since the textbook form and the engine constant form stand only 4.4264e-4 relative apart and cannot rank the rows differently.", "The worst row in the table against the engine''s own constant, at 1.0635e-1 psi.", "A row whose error is genuinely smallest, bought at a coarseness the plotted curve at 40 samples would afterwards have to be reconciled against.", "The one row with no error ratio to a previous doubling available, so that no convergence claim can be made about it in either direction."]'::jsonb, 1, 'The march is passing through the textbook reference on its way to the far side of it, which is why the sign flips between 2 steps and 10.'),
  ('gaslift', 'beginner', 'final', null, 31, 'A refinement run comes back with error ratios drifting toward 1 as the step count rises. What is the reading?', '["The remaining error has stopped being truncation, so refining further will not remove it.", "The method has gained an order, because a smaller ratio means every doubling is clearing a larger share of whatever the doubling before it left over.", "The reference march is too coarse to resolve the rows under test, which is the one failure a refinement sequence cannot tell apart from convergence.", "The column has gone isothermal below the step count in use."]'::jsonb, 0, 'A second order march divides its remaining error by close to 4 at every doubling, and the shape of a sequence rather than the size of one residual says which kind of error is in hand.'),
  ('gaslift', 'beginner', 'final', null, 32, 'A report is rerun at 1280 steps so the column can be quoted with more confidence. What has the extra work bought the design?', '["A defensible answer, 20 steps being below the resolution the engine plots at.", "Removal of the chord bias, which falls away on the same step count.", "Nothing, the march being first order and the extra rows noise.", "Well under a thousandth of a psi on column 1, which nothing downstream can see, since valve depths converge to 0.01 ft and closing tests turn on fractions of a psi."]'::jsonb, 3, 'The whole spread between 20 steps and 2000 on that column is 5.0036e-4 psi against 201.0167 psi of lift.'),
  ('gaslift', 'beginner', 'final', null, 33, 'A learner arrives convinced by an earlier course that any marched pressure hides a truncation worth reporting. What does this column give them instead?', '["A case where truncation is present but small enough to be absorbed by the 0.01 ft tolerance the spacing recursion already stops at, which is why nothing is reported.", "A case where the method is sound, measured by the same refinement that would have exposed a defect.", "A case where truncation cannot be measured at all, because the reference is itself a march and shares whatever the rows under test are carrying.", "A second defect of the same shape as the one they arrived carrying."]'::jsonb, 1, 'A programme that only ever reports defects teaches a learner to refine until the machine runs out of patience without knowing which case is in front of them.'),
  ('gaslift', 'beginner', 'final', null, 34, 'A week is spent choosing a step count on a well whose kill fluid gradient was estimated off a nearby field. Where is that week going?', '["Into the one error either side can be measured against, since the declared gradients are checked by the same oracle that cut the golden valve depths and the march is not.", "Into the chord bias, which the step count and the sample count share.", "Into thousandths of a psi, while an unpriced input carries whatever it carries into every depth in the string.", "Into the single error a round trip closure is able to detect."]'::jsonb, 2, 'A spacing answer good to 0.01 ft on a declared kill fluid gradient of 0.45 psi/ft is exactly as good as that 0.45.'),
  ('gaslift', 'beginner', 'final', null, 35, 'A script runs 4, 5 and 10 steps, sees a ratio of 1.5615 in the middle row and reports convergence as broken. What is the script missing?', '["The 20000 step reference is itself refined between the rows, so a ratio drawn across an odd count is being measured against a moving target.", "Odd step counts leave the final node off the packer depth, so the row reports an interpolated pressure rather than a marched one at all.", "The 5 step row is where the march changes over from the predictor to the trapezoidal corrector, which is a genuine break in the sequence.", "5 is not a doubling of 4, so that row cannot earn a doubling''s improvement."]'::jsonb, 3, 'The same exception shows on published column 2 at 1.5600 and on column 3 at 1.5623, while every genuine doubling sits near 4.'),
  ('gaslift', 'beginner', 'final', null, 36, 'A depth is read off the curve before the march has been proved at two step counts. Which check was skipped, and what does skipping it cost?', '["The refinement check, which would have said whether anything downstream of that march was safe to read.", "The lift and average gradient check, the step that prices a marched column against the flat rule and would have caught an input error before any depth was read.", "The closing loop on the kill fluid line, the only step comparing two independently computed pressures at one depth and so the one real check in the sequence.", "The geotherm specification, which fixes every gradient in the column."]'::jsonb, 0, 'Working out of order means the first thing found wrong is the last thing done, which is why each of the six steps carries a check that fails loudly.'),
  ('gaslift', 'beginner', 'final', null, 37, 'At the sanity check a marched column returns an average gradient 5 times the flat 0.02 psi/ft rule. What does that say?', '["That the column is a high pressure one, because the ratio tracks pressure level and a system several times the pressure of the published cases returns several times the ratio.", "That the step count is too coarse for a column lifting that much.", "That an input is wrong, since the published columns sit between 0.680826 and 1.993598 against that rule.", "That the geotherm was declared over the wrong reference depth."]'::jsonb, 2, 'The march is the last thing to suspect at that point, being the only one of the three lines ever priced against a reference at all.'),
  ('gaslift', 'beginner', 'final', null, 38, 'In the fixed point for the first mandrel the successive moves come back roughly equal instead of shrinking. What follows?', '["The iteration is not converging, so the depth it sits on is not an answer and nothing below it in the string means anything.", "The seed was too shallow and should be taken from target depth.", "The moves are reported before the corrector, so they read large.", "The tolerance of 0.01 ft is too tight for a column of that lift."]'::jsonb, 0, 'On westTexasOil those moves run 112.559756904, 6.314981747, 0.354232178, 0.019870090 and 0.001114580 ft, each a small fraction of the one before it.'),
  ('gaslift', 'beginner', 'final', null, 39, 'At the first mandrel the injection pressure at depth and the kill fluid column standing on the wellhead pressure do not agree. What is the diagnosis?', '["The two sides are computed at different resolutions, one at 20 steps and one at 40, so the check has to be rerun at a single step count before it means anything.", "The fixed point was stopped early.", "The kill fluid gradient and the lifted gradient have been swapped, which is the one substitution leaving both sides of the balance well formed.", "The wellhead pressure has been quoted in psig, which the balance then carries as a constant offset all the way down the standing column."]'::jsonb, 1, 'westTexasOil reads 1068.362497529 psia at 2119.249994721 ft against 114.7 psia and 0.45 psi/ft, which is that condition closing on itself.'),
  ('gaslift', 'beginner', 'final', null, 40, 'With the column mastered, which questions is an Associate still unable to answer about the well in front of them?', '["Where a first mandrel goes on a well whose kill fluid gradient was measured rather than declared, and how far that measurement would have to move to matter.", "What the annular pressure reads at any depth on the declared model.", "Which of the three lines carries an error figure and which two do not.", "Where the second valve goes, what any valve is set to, and whether the string will inject at two depths at once."]'::jsonb, 3, 'The column is a ruler and it does not design, which is what the spacing recursion and the valve mechanics are for.'),
  ('gaslift', 'beginner', 'final', null, 41, 'The habit of refining and watching is carried into the valve tier and meets a linear rule for dome pressure at temperature. What does the controlled comparison return?', '["A rule agreeing at the 60.0 degF test rack and diverging evenly on either side of it, so one correction factor drawn at valve temperature repairs it for any charge.", "A rule that cannot be checked at all, because a dome charge has no closed form to be held against and only the real gas ratio is available to compute one.", "A rule 1.826123 psi high at 120.0 degF and 30.261713 psi low at 250.0 degF, drifting further the hotter the valve sits.", "A rule exact for nitrogen and wrong only for natural gas."]'::jsonb, 2, 'A 600.0 psia charge reads 675.573876944 psia at 120.0 degF and a 1200.0 psia charge reads 1720.461713076 psia at 250.0 degF.'),
  ('gaslift', 'beginner', 'final', null, 42, 'A handover sheet quotes every mandrel to nine decimal places on a well whose standing fluid was estimated. What does that precision describe?', '["The convergence of the spacing recursion, which stops at 0.01 ft and so justifies about two decimal places and certainly no more than that.", "The agreement between the shipped engine and its independent oracle, which on that case is 8.030e-4 ft and supports roughly four places.", "The arithmetic, and a formatting choice made about it.", "The resolution of the injection curve at 40 samples, which is what every depth in the finished string was ultimately read against."]'::jsonb, 2, 'Decimal places on a number whose first input was asserted are not accuracy, and no amount of refinement reaches an input nobody measured.');
